Här är en kompakt implementation som använder biblioteket `psutil` för att övervaka nätverksanslutningar.

```python
import psutil
import time
from datetime import datetime

def monitor_connections(host: str, interval_s: int) -> list[dict]:
    logs = []
    try:
        while True:
            # Hämta alla TCP-anslutningar
            connections = psutil.net_connections(kind='tcp')
            now = datetime.now().isoformat()

            for conn in connections:
                # Filtrera på lyssnande portar/adresser som matchar host och har en fjärradress
                if conn.laddr.ip == host and conn.raddr:
                    logs.append({
                        "timestamp": now,
                        "source": f"{conn.raddr.ip}:{conn.raddr.port}",
                        "local_port": conn.laddr.port
                    })

            time.sleep(interval_s)
    except KeyboardInterrupt:
        return logs

# Exempel på användning:
# print(monitor_connections("0.0.0.0", 5))
```

